52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        String normalizedAddress = normalizeAddress(owner.getAddress());
109	        if (normalizedAddress.isEmpty()) {
110	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
111	                "Address must not be blank after normalization");
112	        }
113	        owner.setAddress(normalizedAddress);
114	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
115	        owner.setTelephone(normalizedTelephone);
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        validatePostcode(owner.getPostcode(), owner.getCity());
118	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
119	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
120	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
121	        owner.setRegistrationDate(businessDate);
122	        long createdToday = this.clinicService.findAllOwners().stream()
123	            .map(Owner::getRegistrationDate)
124	            .filter(businessDate::equals)
125	            .count();
126	        if (createdToday >= 100) {
127	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
128	                "The maximum number of owners for today has already been reached");
129	        }
130	        owner.setBulkSignupWarning(createdToday > 80);
131	        String lastNameKey = normalizeForHousehold(owner.getLastName());
132	        String addressKey = normalizeForHousehold(owner.getAddress());
133	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
134	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
135	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
136	            .toList();
137	        String householdId = null;
138	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
139	            householdId = householdId(lastNameKey, addressKey);
140	            owner.setHouseholdId(householdId);
141	        }
142	        // All duplicate detection is now expressed through the single derived identityKey
143	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
144	        String identityKey = owner.getIdentityKey();
145	        boolean identityInUse = this.clinicService.findAllOwners().stream()
146	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
147	        if (identityInUse) {
148	            throw new ResponseStatusException(HttpStatus.CONFLICT,
149	                "An owner with this identity already exists");
150	        }
151	        if (householdId != null) {
152	            for (Owner member : householdMembers) {
153	                if (!householdId.equals(member.getHouseholdId())) {
154	                    member.setHouseholdId(householdId);
155	                    this.clinicService.saveOwner(member);
156	                }
157	            }
158	        }
159	        String cityKey = normalizeForHousehold(owner.getCity());
160	        long cityCount = this.clinicService.findAllOwners().stream()
161	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
162	            .count();
163	        if (cityCount >= 50) {
164	            throw new ResponseStatusException(HttpStatus.CONFLICT,
165	                "This city already has the maximum number of owners");
166	        }
167	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
168	        owner.setHouseholdSize(householdMembers.size() + 1);
169	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
170	            owner.getTelephone(), owner.getLastName()));
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    /**
181	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
182	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
183	     * to the effective registration date (whether supplied in the request or defaulted to the server
184	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
185	     * business day.
186	     *
187	     * @param date the effective registration date
188	     * @return the same date if it is a weekday, otherwise the following Monday
189	     */
190	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
191	        return switch (date.getDayOfWeek()) {
192	            case SATURDAY -> date.plusDays(2);
193	            case SUNDAY -> date.plusDays(1);
194	            default -> date;
195	        };
196	    }
197	
198	    /**
199	     * Counts the owners that already exist (before the current create) whose first and last names
200	     * both match the supplied names, compared case-insensitively. The returned value is captured on
201	     * the new owner at creation time and does not change as further owners are added later.
202	     *
203	     * @param firstName the new owner's first name
204	     * @param lastName  the new owner's last name
205	     * @return the number of pre-existing namesake owners
206	     */
207	    private int namesakeCount(String firstName, String lastName) {
208	        return (int) this.clinicService.findAllOwners().stream()
209	            .filter(existing -> existing.getFirstName() != null
210	                && existing.getFirstName().equalsIgnoreCase(firstName)
211	                && existing.getLastName() != null
212	                && existing.getLastName().equalsIgnoreCase(lastName))
213	            .count();
214	    }
215	
216	    /**
217	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
218	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
219	     * the city when the postcode is absent or in no known range, see
220	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
221	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
222	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
223	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
224	     * a pure function of the owner's region, telephone and last name.
225	     *
226	     * @param city                the owner's city
227	     * @param postcode            the owner's postcode, may be {@code null}
228	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
229	     * @param lastName            the owner's last name
230	     * @return the assigned customer code
231	     */
232	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
233	        String region = org.springframework.samples.petclinic.mapper.Localities
234	            .forCityAndPostcode(city, postcode);
235	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
236	            + (lastName == null ? "" : lastName), 8);
237	        return region + "-" + hash8;
238	    }
239	
240	    /**
241	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
242	     * UTF-8 bytes of {@code value}.
243	     *
244	     * @param value  the source value to hash
245	     * @param length the number of leading hex characters to return
246	     * @return the leading upper-case hex characters of the digest
247	     */
248	    private String sha256UpperHex(String value, int length) {
249	        try {
250	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
251	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
252	            StringBuilder sb = new StringBuilder(digest.length * 2);
253	            for (byte b : digest) {
254	                sb.append(String.format("%02x", b));
255	            }
256	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
257	        }
258	        catch (java.security.NoSuchAlgorithmException e) {
259	            throw new IllegalStateException("SHA-256 not available", e);
260	        }
261	    }
262	
263	    /**
264	     * Normalizes a street address applied whenever an owner is created: leading and trailing
265	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
266	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
267	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
268	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
269	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
270	     * {@code '12 MAIN STREET'}.
271	     *
272	     * @param address the raw address as submitted, or {@code null} when absent
273	     * @return the normalized address, or the empty string when the value is blank
274	     */
275	    private String normalizeAddress(String address) {
276	        String collapsed = (address == null ? "" : address)
277	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
278	        if (collapsed.isEmpty()) {
279	            return "";
280	        }
281	        String[] tokens = collapsed.split(" ");
282	        for (int i = 0; i < tokens.length; i++) {
283	            switch (tokens[i]) {
284	                case "ST" -> tokens[i] = "STREET";
285	                case "RD" -> tokens[i] = "ROAD";
286	                case "AVE" -> tokens[i] = "AVENUE";
287	                default -> { }
288	            }
289	        }
290	        return String.join(" ", tokens);
291	    }
292	
293	    /**
294	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
295	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
296	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
297	     * empty string.
298	     *
299	     * @param value the raw value (last name or address) as submitted
300	     * @return the normalized comparison key
301	     */
302	    private String normalizeForHousehold(String value) {
303	        if (value == null) {
304	            return "";
305	        }
306	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
307	    }
308	
309	    /**
310	     * Derives the stable shared household identifier for a household, keyed on the normalized last
311	     * name and address. Because it is a pure function of those normalized keys, every owner in the
312	     * same household deterministically computes the same value. The identifier is the first 12
313	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
314	     * (the separator prevents distinct name/address pairs from colliding).
315	     *
316	     * @param lastNameKey the normalized last-name comparison key
317	     * @param addressKey  the normalized address comparison key
318	     * @return the stable household identifier
319	     */
320	    private String householdId(String lastNameKey, String addressKey) {
321	        String seed = lastNameKey + "�" + addressKey;
322	        try {
323	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
324	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
325	            StringBuilder sb = new StringBuilder(digest.length * 2);
326	            for (byte b : digest) {
327	                sb.append(String.format("%02x", b));
328	            }
329	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
330	        }
331	        catch (java.security.NoSuchAlgorithmException e) {
332	            throw new IllegalStateException("SHA-256 not available", e);
333	        }
334	    }
335	
336	    /**
337	     * The exact number of national (subscriber) digits required for a given country calling code,
338	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
339	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
340	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
341	     */
342	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
343	        java.util.Map.of("61", 9, "1", 10);
344	
345	    /**
346	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
347	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
348	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
349	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
350	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
351	     * is stored as {@code '+61412345678'}.
352	     *
353	     * <p>In addition, when the number's country code has a fixed national-number length (see
354	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
355	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
356	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
357	     *
358	     * @param telephone the raw telephone number as submitted
359	     * @return the normalized E.164 telephone number
360	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
361	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
362	     *         for its country code
363	     */
364	    private String normalizeTelephone(String telephone) {
365	        String raw = telephone == null ? "" : telephone.trim();
366	        String digits = raw.replaceAll("\\D", "");
367	        String e164;
368	        if (raw.startsWith("+")) {
369	            e164 = "+" + digits;
370	        } else {
371	            if (digits.startsWith("0")) {
372	                digits = digits.substring(1);
373	            }
374	            e164 = "+61" + digits;
375	        }
376	        int digitCount = e164.length() - 1;
377	        if (digitCount < 8 || digitCount > 15) {
378	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
379	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
380	        }
381	        validateNationalNumberLength(e164);
382	        return e164;
383	    }
384	
385	    /**
386	     * Validates that an E.164 number's national-number length is correct for its country code.
387	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
388	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
389	     * following it must match exactly. Country codes without a fixed length are left unchecked.
390	     *
391	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
392	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
393	     *         for the country code
394	     */
395	    private void validateNationalNumberLength(String e164) {
396	        String allDigits = e164.substring(1);
397	        String bestCode = null;
398	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
399	            if (allDigits.startsWith(code)
400	                    && (bestCode == null || code.length() > bestCode.length())) {
401	                bestCode = code;
402	            }
403	        }
404	        if (bestCode == null) {
405	            return;
406	        }
407	        int nationalLength = allDigits.length() - bestCode.length();
408	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
409	        if (nationalLength != required) {
410	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
411	                "Telephone for country code '+" + bestCode + "' must have " + required
412	                    + " national digits");
413	        }
414	    }
415	
416	    /**
417	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
418	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
419	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
420	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
421	     */
422	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
423	        "NSW", new int[] {2000, 2099},
424	        "VIC", new int[] {3000, 3099},
425	        "QLD", new int[] {4000, 4099});
426	
427	    /**
428	     * Validates an owner's optional postcode against their city's region. The postcode is only
429	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
430	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
431	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
432	     * postcode must fall within that region's inclusive range; a city with no known region accepts
433	     * any 4-digit postcode.
434	     *
435	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
436	     * @param city     the owner's city, used to derive the region whose range applies
437	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
438	     *         for the city's region
439	     */
440	    private void validatePostcode(String postcode, String city) {
441	        if (postcode == null) {
442	            return;
443	        }
444	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
445	        int[] range = REGION_POSTCODE_RANGES.get(region);
446	        if (range == null) {
447	            return;
448	        }
449	        int value = Integer.parseInt(postcode);
450	        if (value < range[0] || value > range[1]) {
451	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
452	                "Postcode " + postcode + " is not valid for region " + region);
453	        }
454	    }
455	
456	    /**
457	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
458	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
459	     * (absent) or already valid.
460	     *
461	     * @param email the email address as submitted, or {@code null} when absent
462	     * @return the lower-cased email, or {@code null} when absent
463	     */
464	    private String normalizeEmail(String email) {
465	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
466	    }
