730	    /**
731	     * The single derived key used for all duplicate detection, formatted
732	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
733	     * duplicates only when their whole identity keys are equal; because the telephone is part
734	     * of the key, two members of the same household with different telephones have different
735	     * keys and are both allowed.
736	     *
737	     * @return the derived identity key
738	     */
739	    @Transient
740	    public String getIdentityKey() {
741	        return (this.telephone == null ? "" : this.telephone) + "|"
742	            + (this.email == null ? "" : this.email) + "|"
743	            + (this.householdId == null ? "" : this.householdId);
744	    }
745	
746	    /**
747	     * A single Luhn check digit (0-9) computed over the digits contained in the
748	     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
749	     * separators) are ignored; a {@code null} customer code is treated as having no digits.
750	     *
751	     * @return the Luhn check digit for the customer code
752	     */
753	    @Transient
754	    public int getCheckDigit() {
755	        String source = this.customerCode == null ? "" : this.customerCode;
756	        int sum = 0;
757	        boolean dbl = true;
758	        for (int i = source.length() - 1; i >= 0; i--) {
759	            char c = source.charAt(i);
760	            if (c < '0' || c > '9') {
761	                continue;
762	            }
763	            int d = c - '0';
764	            if (dbl) {
765	                d *= 2;
766	                if (d > 9) {
767	                    d -= 9;
768	                }
769	            }
770	            sum += d;
771	            dbl = !dbl;
772	        }
773	        return (10 - (sum % 10)) % 10;
774	    }
